export interface TpFlyer { nome: string; dir: string; pages: number[] }
export interface TpShop { slug: string; cat: TpCategory; logo: string; name: string; flyers: TpFlyer[] }

const TPBASE = 'https://www.tuttiprezzi.it';
export const tpLogoUrl = (slug: string) => `${TPBASE}/BOX/${slug}.png`;
export const tpPageUrl = (dir: string, page: number) => `${TPBASE}/${dir}/new/p_Page_${page.toString().padStart(2, '0')}.jpg`;


